def apply(inputs, premises):
    question = str(inputs.get("question", "")).casefold() if isinstance(inputs, dict) else ""
    employee_query = "employee" in question or "staff" in question
    external_query = ("third-part" in question or "consultant" in question or "contractor" in question or "agent" in question or "professional advisor" in question or "professional adviser" in question or "legal advisor" in question or "legal adviser" in question or "financial advisor" in question or "financial adviser" in question or "accountant" in question or "lender" in question)
    if employee_query == external_query:
        return {"handled": False, "answer": "NotMentioned", "used_records": []}
    records = premises.get("records", []) if isinstance(premises, dict) else []
    if not isinstance(records, list):
        return {"handled": False, "answer": "NotMentioned", "used_records": []}
    allowed_bases = set(["express_role_permission", "exception_role_permission", "restricted_access_role_permission", "internal_operational_permission"])
    external_roles = set(["contractor", "consultant", "agent", "legal_advisor", "financial_advisor", "professional_advisor", "accountant", "lender"])
    employee_permission = -1
    external_permission = -1
    employee_prohibition = -1
    broad_external_prohibition = -1
    ambiguous_external_rule = -1
    employee_scoped_nonanswer = -1
    disclose_base = -1
    access_base = -1
    internal_base = -1
    employee_link = -1
    employee_link_action = ""
    external_link = -1
    external_link_action = ""
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        kind = str(record.get("kind", ""))
        unresolved = record.get("unresolved_fields", [])
        values = record.get("values", {})
        if not isinstance(unresolved, list) or not isinstance(values, dict):
            continue
        if kind == "confidential_information_disclosure_rule":
            if "legal_effect" in unresolved or "action" in unresolved:
                continue
            try:
                effect = str(values["legal_effect"]).casefold()
                action = str(values["action"]).casefold()
            except (KeyError, TypeError):
                continue
            scope = ""
            affiliation = ""
            basis = ""
            classes = []
            if "recipient_scope" not in unresolved:
                try:
                    scope = str(values["recipient_scope"]).casefold()
                except (KeyError, TypeError):
                    scope = ""
            if "recipient_affiliation" not in unresolved:
                try:
                    affiliation = str(values["recipient_affiliation"]).casefold()
                except (KeyError, TypeError):
                    affiliation = ""
            if "authorization_basis" not in unresolved:
                try:
                    basis = str(values["authorization_basis"]).casefold()
                except (KeyError, TypeError):
                    basis = ""
            if "recipient_classes" not in unresolved:
                try:
                    raw_classes = values["recipient_classes"]
                    if isinstance(raw_classes, (list, tuple)):
                        classes = [str(item).casefold() for item in raw_classes]
                except (KeyError, TypeError):
                    classes = []
            if effect == "permission" and basis in allowed_bases:
                if action == "disclose_confidential_information" and disclose_base < 0:
                    disclose_base = index
                elif action == "grant_access_to_confidential_information" and access_base < 0:
                    access_base = index
                elif action == "internally_share_confidential_information" and internal_base < 0:
                    internal_base = index
                if employee_permission < 0:
                    if scope == "internal_personnel" or ("employee" in classes and affiliation in set(["actor_internal_personnel", "mixed_actor_representatives"])):
                        employee_permission = index
                if external_permission < 0:
                    role_match = any(role in external_roles for role in classes)
                    external_affiliation = affiliation in set(["actor_external_representative", "unrelated_external", "mixed_actor_representatives"])
                    if scope in set(["broad_third_party", "broad_external_person"]) or (role_match and external_affiliation):
                        external_permission = index
            elif effect == "prohibition":
                if scope in set(["broad_third_party", "broad_external_person", "unspecified_external_person"]):
                    if basis == "purpose_exception_unspecified_recipient":
                        if ambiguous_external_rule < 0:
                            ambiguous_external_rule = index
                    elif basis != "":
                        if broad_external_prohibition < 0:
                            broad_external_prohibition = index
                    if employee_scoped_nonanswer < 0:
                        employee_scoped_nonanswer = index
                if employee_prohibition < 0:
                    if scope == "internal_personnel" or ("employee" in classes and affiliation in set(["actor_internal_personnel", "mixed_actor_representatives"])):
                        employee_prohibition = index
        elif kind == "recipient_scope_link":
            required = ["target_legal_effect", "target_action", "recipient_classes", "recipient_affiliation", "link_semantics"]
            if any(field in unresolved for field in required):
                continue
            try:
                target_effect = str(values["target_legal_effect"]).casefold()
                target_action = str(values["target_action"]).casefold()
                raw_classes = values["recipient_classes"]
                affiliation = str(values["recipient_affiliation"]).casefold()
                link_semantics = str(values["link_semantics"]).casefold()
            except (KeyError, TypeError):
                continue
            if not isinstance(raw_classes, (list, tuple)):
                continue
            classes = [str(item).casefold() for item in raw_classes]
            if target_effect != "permission" or link_semantics not in set(["expands_authorized_scope", "presupposes_authorized_scope"]):
                continue
            if employee_link < 0 and "employee" in classes and affiliation in set(["actor_internal_personnel", "mixed_actor_representatives"]):
                employee_link = index
                employee_link_action = target_action
            role_match = any(role in external_roles for role in classes)
            if external_link < 0 and role_match and affiliation in set(["actor_external_representative", "unrelated_external", "mixed_actor_representatives"]):
                external_link = index
                external_link_action = target_action
    if employee_query:
        if employee_permission >= 0:
            return {"handled": True, "answer": "Entailment", "used_records": [employee_permission]}
        if employee_link >= 0:
            base = -1
            if employee_link_action == "disclose_confidential_information":
                base = disclose_base
            elif employee_link_action == "grant_access_to_confidential_information":
                base = access_base
            elif employee_link_action == "internally_share_confidential_information":
                base = internal_base
            if base >= 0:
                return {"handled": True, "answer": "Entailment", "used_records": [base, employee_link]}
        if employee_prohibition >= 0:
            return {"handled": True, "answer": "Contradiction", "used_records": [employee_prohibition]}
        if employee_scoped_nonanswer >= 0:
            return {"handled": True, "answer": "NotMentioned", "used_records": [employee_scoped_nonanswer]}
        return {"handled": False, "answer": "NotMentioned", "used_records": []}
    if external_permission >= 0:
        return {"handled": True, "answer": "Entailment", "used_records": [external_permission]}
    if external_link >= 0:
        base = -1
        if external_link_action == "disclose_confidential_information":
            base = disclose_base
        elif external_link_action == "grant_access_to_confidential_information":
            base = access_base
        elif external_link_action == "internally_share_confidential_information":
            base = internal_base
        if base >= 0:
            return {"handled": True, "answer": "Entailment", "used_records": [base, external_link]}
    if ambiguous_external_rule >= 0:
        return {"handled": True, "answer": "NotMentioned", "used_records": [ambiguous_external_rule]}
    if broad_external_prohibition >= 0:
        return {"handled": True, "answer": "Contradiction", "used_records": [broad_external_prohibition]}
    return {"handled": False, "answer": "NotMentioned", "used_records": []}
